// Blocks `git commit` on main. Exits 2 (block) whenever it cannot decide.
import { readFileSync } from 'node:fs';
import { execSync } from 'node:child_process';
try {
  const command = JSON.parse(readFileSync(0, 'utf8')).tool_input?.command ?? '';
  if (!/\bgit\s+commit\b/.test(command)) process.exit(0);
  if (execSync('git branch --show-current').toString().trim() !== 'main') process.exit(0);
  console.error('Commits on main are blocked. Create a feature branch: git switch -c <name>');
} catch {}
process.exit(2);
